#define FMT_HEADER_ONLY
#include "fmt/ostream.h"
#include <string>
#include <iostream>
int main() {
  fmt::MemoryWriter w;
  size_t final_len = 0;
  const size_t l = 10000;
  for (size_t i = 0; i < l; ++i) {
    const std::string token = std::to_string(i);
    final_len += token.size();
    w << token;
  }
  const std::string rs = w.str();
  if (w.size() != final_len || rs.size() != final_len) {
    std::cerr << w.size() << " " << final_len << " " << rs.size() << "\n";
    return 1;
  }
  return 0;
}
